import { Component, Element, Event, EventEmitter, h, Host, Prop } from '@stencil/core';
import { TagColor, TagVariant } from '../../types';

/**
 * @slot default - default slot for the content of the tag (here is any HTML content allowed)
 */
@Component({
  tag: 'groupui-tag',
  styleUrl: 'tag.scss',
  shadow: true,
})
export class Tag {
  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly square: boolean;

  /**
   * color of the tag (default: information)
   */
  @Prop({ reflect: true }) readonly color: TagColor;

  /**
   * variant of the tag (default: primary)
   */
  @Prop({ reflect: true }) readonly variant: TagVariant = 'primary';

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  render() {
    return (
      <Host>
        <slot></slot>
      </Host>
    );
  }
}
